import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { socket } from './socket';
import './DMPage.css';

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  // Add this check immediately
  if (!currentUser || !currentUser._id) {
    navigate('/homes'); // or return a loading state
    return null;
  }
  const [applications, setApplications] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState({
    applications: false,
    messages: false,
    sending: false
  });
  const messagesEndRef = useRef(null);
  const defaultAvatar = '/default-avatar.png';

  const fetchApplications = async () => {
    const token = localStorage.getItem("token");
    setLoading(prev => ({ ...prev, applications: true }));

    if (!token) {
      console.error("❌ No token found in localStorage");
      setLoading(prev => ({ ...prev, applications: false }));
      return;
    }

    try {
      const res = await fetch("http://localhost:3000/api/applications", {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      const data = await res.json();
      setApplications(data);
    } catch (error) {
      console.error("❌ Error fetching applications:", error.message);
    } finally {
      setLoading(prev => ({ ...prev, applications: false }));
    }
  };

  const fetchChatMessages = async (applicantId) => {
    if (!applicantId || !currentUser?._id) return;

    setLoading(prev => ({ ...prev, messages: true }));
    try {
      const res = await axios.get(
        `http://localhost:3000/api/messages?userId=${currentUser._id}&otherUserId=${applicantId}`
      );
      setMessages(res.data);
    } catch (error) {
      console.error('Error fetching chat messages:', error);
    } finally {
      setLoading(prev => ({ ...prev, messages: false }));
    }
  };

  useEffect(() => {
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');

    if (!token || !userData) {
      navigate('/login');
      return;
    }

    socket.auth = { token };
    socket.connect();
    // Add null check before emitting
  if (currentUser._id) {
    socket.emit("register", currentUser._id);
  }


    fetchApplications();

    // Set up socket listeners
    const handleReceiveMessage = (message) => {
      if (!selectedUser) return;

      if (
        (message.sender === currentUser._id && message.receiver === selectedUser._id) ||
        (message.receiver === currentUser._id && message.sender === selectedUser._id)
      ) {
        setMessages(prev => [...prev, message]);
      }
    };

    socket.on('receiveMessage', handleReceiveMessage);

    return () => {
      socket.off('receiveMessage', handleReceiveMessage);
      socket.disconnect();
    };
  }, [currentUser, navigate]);

  useEffect(() => {
    if (selectedUser) {
      fetchChatMessages(selectedUser._id);
    }
  }, [selectedUser]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!newMessage.trim() || !selectedUser || loading.sending) return;

    setLoading(prev => ({ ...prev, sending: true }));
    const messageData = {
      sender: currentUser._id,
      receiver: selectedUser._id,
      message: newMessage.trim(),
      timestamp: new Date().toISOString(),
    };

    try {
      socket.emit('sendMessage', messageData);
      setMessages(prev => [...prev, messageData]);
      setNewMessage('');
    } catch (error) {
      console.error('Error sending message:', error);
    } finally {
      setLoading(prev => ({ ...prev, sending: false }));
    }
  };

  const handleAccept = async () => {
    if (!selectedUser) return;

    const application = applications.find(
      app => app.applicant._id.toString() === selectedUser._id.toString()
    );

    if (!application) {
      console.error('No application found for this user.');
      return;
    }

    try {
      await axios.put('http://localhost:3000/api/applications/accept', {
        applicantId: application.applicant._id,
        clientId: currentUser._id,
      }, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });

      setApplications(prev =>
        prev.map(app =>
          app._id === application._id ? { ...app, status: 'accepted' } : app
        )
      );
    } catch (error) {
      console.error('Error accepting application:', error);
    }
  };

  const renderApplicants = () => {
    if (loading.applications) return <div className="empty-list">Loading...</div>;
    if (applications.length === 0) return <div className="empty-list">No applications yet</div>;

    return applications.map((app) => {
      // Add null checks for applicant data
      const applicant = app?.applicant || {};
      return (
        <div
          key={app?._id || Math.random()}
          className={`applicant-item ${selectedUser?._id === applicant?._id ? 'active' : ''}`}
          onClick={() => applicant?._id && setSelectedUser(applicant)}
        >
          <img
            src={applicant?.image || defaultAvatar}
            alt={applicant?.name || 'User'}
            className="user-avatar"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = defaultAvatar;
            }}
          />
          <div className="applicant-info">
            <h3>{applicant?.name || 'Unknown User'}</h3>
            <p className="status">{app?.status || 'pending'}</p>
            <p className="message-preview">
              {app?.message ? app.message.substring(0, 30) + '...' : ''}
            </p>
          </div>
        </div>
      );
    });
  };

  const renderMessages = () => {
    if (loading.messages) return <div className="loading-messages">Loading messages...</div>;

    return messages.map((msg, index) => (
      <div
        key={msg._id || index}
        className={`message ${msg.sender === currentUser._id ? 'sent' : 'received'}`}
      >
        <p className="message-content">{msg.message}</p>
        <p className="message-time">
          {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
        </p>
      </div>
    ));
  };

  return (
    <div className="dm-container">
      <div className="dm-sidebar">
        <h2>Applicants</h2>
        {renderApplicants()}
      </div>

      <div className="chat-area">
        {selectedUser ? (
          <>
            <div className="chat-header">
  <img
    src={selectedUser?.image || defaultAvatar}
    alt={selectedUser?.name || 'User'}
    className="user-avatar"
    onError={(e) => {
      e.target.onerror = null;
      e.target.src = defaultAvatar;
    }}
  />
  <div className="header-info">
    <h3>{selectedUser?.name || 'User'}</h3>
    <p className="status">
      {applications.find(app => app?.applicant?._id === selectedUser?._id)?.status || 'pending'}
    </p>
  </div>
  <button 
    onClick={handleAccept} 
    className="accept-btn"
    disabled={applications.find(app => app?.applicant?._id === selectedUser?._id)?.status === 'accepted'}
  >
    {applications.find(app => app?.applicant?._id === selectedUser?._id)?.status === 'accepted'
      ? 'Accepted'
      : 'Accept Client'}
  </button>
</div>

            <div className="messages-container">
              {renderMessages()}
              <div ref={messagesEndRef} />
            </div>

            <div className="message-input">
              <input
                type="text"
                placeholder="Type a message..."
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                disabled={loading.sending}
              />
              <button 
                onClick={handleSend} 
                disabled={!newMessage.trim() || loading.sending}
              >
                {loading.sending ? 'Sending...' : 'Send'}
              </button>
            </div>
          </>
        ) : (
          <div className="empty-chat">
            {loading.applications ? 'Loading...' : 'Select an applicant to start chatting'}
          </div>
        )}
      </div>
    </div>
  );
};

export default DMPage;
